  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, created_by, updated_by, attribution_type, status)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah yang Sering Muncul$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Motor servo terlihat sederhana, tetapi banyak pemula menemui masalah: servo bergetar (jitter) tanpa bergerak sesuai perintah, hanya bergerak sebagian sudut, tidak kuat mengangkat beban, atau bahkan Arduino ikut restart sendiri saat servo bergerak. Artikel ini memandu Anda memahami cara kerja servo dan memasangnya dengan benar.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'HEADING', 2, jsonb_build_object('text', $txt$Memahami Cara Kerja Motor Servo$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Motor servo dikendalikan sinyal PWM 50 Hz. Lebar pulsa 1 ms memutar horn ke 0 derajat, 1,5 ms ke posisi tengah 90 derajat, dan 2 ms ke 180 derajat. Di dalam servo ada rangkaian yang terus membandingkan posisi aktual dengan posisi perintah, sehingga horn menahan posisinya melawan beban ringan. Tipe umum adalah SG90 (kecil, plastik) dan MG996R (lebih besar, gigi metal, torsi kuat).$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Arduino Uno (atau board kompatibel)$txt$, $txt$Motor servo SG90 untuk latihan, MG996R untuk beban lebih berat$txt$, $txt$Kabel jumper male-to-male$txt$, $txt$Breadboard (opsional)$txt$, $txt$Catu daya eksternal 5V 2A jika memakai servo besar atau lebih dari satu servo$txt$, $txt$Multimeter untuk memeriksa tegangan (opsional)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Pemasangan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$1. Sambungkan kabel merah servo ke 5V dan kabel hitam/cokelat ke GND. 2. Sambungkan kabel sinyal (kuning/oranye) ke pin D9 Arduino. 3. Jika memakai MG996R atau lebih dari satu servo, sambungkan daya servo ke catu daya eksternal, bukan ke pin 5V Arduino, dan satukan GND catu daya dengan GND Arduino. 4. Buka Arduino IDE, sertakan library Servo bawaan. 5. Buat objek Servo, gunakan fungsi attach(9), lalu tulis sudut dengan write(0) sampai write(180). 6. Uji dengan contoh sketch Sweep: servo harus bergerak halus dari 0 ke 180 derajat dan kembali.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'WARNING', 9, jsonb_build_object('text', $txt$Peringatan penting: satu servo MG996R yang bergerak menahan beban dapat menarik arus di atas 500 mA. Mengambil daya dari pin 5V Arduino berisiko merusak port USB komputer atau membuat board restart. Selalu gunakan catu daya eksternal untuk servo besar. Jangan putar horn servo dengan tangan secara paksa karena dapat merusak gigi di dalamnya. Perhatikan polaritas kabel: terbalik bisa merusak servo.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a1, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Servo yang terpasang benar bergerak halus tanpa getar, mencapai sudut penuh 0 sampai 180 derajat, menahan posisi saat diberi beban ringan, dan Arduino tidak restart saat servo bergerak. Jika masih bergetar, periksa kestabilan catu daya dan kualitas kabel jumper. Setelah servo bekerja, Anda bisa melanjutkannya menjadi proyek nyata: lengan robot sederhana, pintu otomatis dengan sensor, atau pan-tilt kamera. Untuk gerakan yang lebih presisi, pelajari fungsi writeMicroseconds untuk mengatur pulsa dalam mikrodetik, bukan hanya sudut.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, created_by, updated_by, attribution_type, status)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah yang Sering Muncul$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Soto Betawi yang gagal biasanya bermasalah pada tiga hal: kuah santan pecah dan berminyak, daging masih alot setelah dimasak lama, atau rasa kuah hambar dan kurang gurih. Artikel ini membahas cara membuat soto Betawi dengan kuah santan yang mulus dan daging yang empuk.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'HEADING', 2, jsonb_build_object('text', $txt$Ciri Khas Soto Betawi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Soto Betawi dikenal dari kuahnya yang memakai santan, kadang dicampur susu, sehingga gurih dan creamy. Isinya berupa potongan daging sapi dan jeroan seperti babat dan paru, disajikan dengan kentang, tomat, emping, bawang goreng, dan sambal. Bumbu halusnya kaya rempah: bawang merah, bawang putih, kemiri, kunyit, jahe, dan ketumbar.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'HEADING', 4, jsonb_build_object('text', $txt$Bahan yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$500 gram daging sapi bagian sandung lamur, potong dadu$txt$, $txt$200 gram jeroan (babat/paru), rebus terpisah lalu potong$txt$, $txt$800 ml santan dari 1 butir kelapa$txt$, $txt$200 ml susu cair plain (opsional, untuk rasa lebih creamy)$txt$, $txt$Bumbu halus: 8 bawang merah, 5 bawang putih, 4 kemiri sangrai, 1 ruas kunyit, 1 ruas jahe, 1 sdt ketumbar$txt$, $txt$2 batang serai, 3 lembar daun salam, 3 lembar daun jeruk, 1 ruas lengkuas$txt$, $txt$Garam, gula, dan kaldu bubuk secukupnya$txt$, $txt$Pelengkap: kentang goreng, tomat, daun bawang, seledri, bawang goreng, emping, jeruk limau, sambal$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Memasak$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$1. Rebus daging dan jeroan hingga empuk, buang buihnya, sisihkan kaldunya. 2. Tumis bumbu halus bersama serai, daun salam, daun jeruk, dan lengkuas hingga harum dan matang. 3. Masukkan tumisan bumbu ke dalam kaldu, didihkan. 4. Tuang santan sedikit demi sedikit sambil terus diaduk perlahan agar tidak pecah. 5. Tambahkan susu cair bila dipakai, bumbui garam, gula, dan kaldu bubuk, koreksi rasa. 6. Masak dengan api kecil sambil sesekali diaduk hingga kuah menyatu dan daging benar-benar empuk.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Hal yang Perlu Diwaspadai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'WARNING', 9, jsonb_build_object('text', $txt$Santan mudah pecah jika dimasak dengan api besar atau jarang diaduk — selalu gunakan api kecil setelah santan masuk dan aduk perlahan. Jeroan harus direbus terpisah dan air rebusannya dibuang agar tidak bau. Jangan terlalu banyak memakai santan kental sekaligus karena kuah bisa menjadi terlalu berat dan enek.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Penyajian$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a2, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Soto Betawi yang berhasil memiliki kuah santan berwarna kuning gading yang mulus tanpa gumpalan, rasa gurih seimbang antara rempah dan santan, daging empuk saat digigit, dan aroma rempah yang harum. Cicipi kuah sebelum disajikan; tambahkan garam atau perasan jeruk limau bila perlu. Sajikan selagi panas dengan pelengkap di atasnya: kentang, tomat, daun bawang, bawang goreng, dan emping di samping. Sisa soto dapat disimpan di kulkas maksimal 2 hari; panaskan kembali dengan api kecil sambil diaduk agar santan tidak pecah.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, created_by, updated_by, attribution_type, status)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'HEADING', 0, jsonb_build_object('text', $txt$Logam Ringan Bernomor Atom 12$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Magnesium adalah unsur kimia dengan simbol Mg dan nomor atom 12, termasuk golongan logam alkali tanah. Ia adalah logam yang ringan, berwarna putih keperakan, dan cukup melimpah di kerak bumi serta terlarut dalam air laut. Secara industri magnesium diekstraksi dari air laut dan mineral seperti dolomit dan magnesit melalui proses elektrolisis atau reduksi termal, dengan permintaan yang terus tumbuh untuk kendaraan listrik dan perangkat elektronik.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'HEADING', 2, jsonb_build_object('text', $txt$Cahaya Putih yang Menyilaukan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Ciri paling terkenal magnesium adalah cara ia terbakar: dengan nyala putih yang sangat terang dan menyilaukan. Reaksinya dengan oksigen menghasilkan magnesium oksida dan melepaskan banyak energi cahaya. Dahulu sifat ini dimanfaatkan untuk lampu kilat (flash) fotografi dan kembang api. Menatap langsung nyala magnesium dapat menyilaukan mata, sehingga percobaan pembakarannya harus memakai pelindung mata.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'HEADING', 4, jsonb_build_object('text', $txt$Sifat Reaktif dan Kegunaannya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Magnesium bereaksi lambat dengan air dingin tetapi cepat dengan air panas dan uap air, menghasilkan magnesium hidroksida dan gas hidrogen; dengan asam encer ia bereaksi kuat menghasilkan garam magnesium dan gas hidrogen. Karena ringan namun kuat, paduan magnesium banyak dipakai pada pelek mobil, rangka sepeda, komponen pesawat terbang, dan casing perangkat elektronik — pengurangan bobot berarti konsumsi bahan bakar lebih hemat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'HEADING', 6, jsonb_build_object('text', $txt$Magnesium dalam Tubuh Manusia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Magnesium adalah mineral penting bagi tubuh: berperan dalam kerja otot dan saraf, menjaga irama jantung, serta membantu pembentukan tulang. Kekurangan magnesium dapat menyebabkan kram otot dan kelelahan. Sumber alaminya antara lain kacang-kacangan, biji-bijian, sayuran hijau, dan pisang.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'HEADING', 8, jsonb_build_object('text', $txt$Fakta Singkat Magnesium$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a3, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Simbol: Mg, nomor atom 12$txt$, $txt$Massa jenis sekitar 1,7 g/cm3 — lebih ringan dari aluminium$txt$, $txt$Titik lebur sekitar 650 derajat Celsius$txt$, $txt$Terbakar di udara dengan nyala putih sangat terang$txt$, $txt$Senyawanya dipakai sebagai antasida (magnesium hidroksida) dan garam epsom (magnesium sulfat)$txt$])));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, created_by, updated_by, attribution_type, status)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'HEADING', 0, jsonb_build_object('text', $txt$Latar Belakang dan Keputusan Bumi Hangus$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah Proklamasi Kemerdekaan 1945, pasukan Sekutu yang diwakili Inggris (AFNEI) datang ke Indonesia dengan misi melucuti tentara Jepang, tetapi kehadiran mereka dimanfaatkan Belanda (NICA) untuk kembali berkuasa. Di Bandung, ketegangan meningkat ketika ultimatum dikeluarkan agar pejuang Indonesia meninggalkan Bandung bagian utara. Pada 23-24 Maret 1946, para pejuang dan pemerintah memutuskan strategi bumi hangus: daripada Bandung utara jatuh utuh ke tangan musuh beserta gudang senjata dan fasilitasnya, lebih baik kota dibakar — keputusan berat yang mengorbankan rumah dan harta benda rakyat sendiri.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'HEADING', 2, jsonb_build_object('text', $txt$Malam 24 Maret 1946$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Menjelang tengah malam, api mulai berkobar di berbagai penjuru Bandung selatan. Gedung-gedung penting, gudang, dan rumah-rumah dibakar oleh para pejuang yang mundur ke selatan, dan langit Bandung memerah diterangi api yang terlihat dari kejauhan. Ratusan ribu warga mengungsi ke arah selatan kota dengan membawa barang seadanya, meninggalkan rumah dan kampung halaman dalam keadaan darurat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'HEADING', 4, jsonb_build_object('text', $txt$Tokoh dan Lagu Perjuangan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Peristiwa ini melibatkan para komandan pejuang di Bandung serta didukung keputusan pimpinan pemerintahan, dengan nama seperti Kolonel A.H. Nasution tercatat dalam rangkaian pertempuran di Bandung pada masa itu. Kekuatan peristiwa ini justru terletak pada partisipasi rakyat: pembakaran dilakukan secara terorganisir oleh barisan pejuang bersama warga. Peristiwa ini diabadikan dalam lagu perjuangan Halo-Halo Bandung ciptaan Ismail Marzuki yang dinyanyikan turun-temurun sebagai pengingat pengorbanan tersebut.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'HEADING', 6, jsonb_build_object('text', $txt$Makna dalam Sejarah Indonesia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Bandung Lautan Api menunjukkan strategi dan tekad mempertahankan kemerdekaan: rakyat rela kehilangan segalanya daripada menyerahkannya kepada penjajah. Peristiwa ini menjadi salah satu episode penting Revolusi Nasional Indonesia 1945-1949 dan diperingati setiap 24 Maret di Kota Bandung dengan berbagai kegiatan mengenang perjuangan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'HEADING', 8, jsonb_build_object('text', $txt$Monumen dan Peringatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a4, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Monumen Bandung Lautan Api di kawasan Tegallega$txt$, $txt$Lapangan Tegallega sebagai pusat peringatan$txt$, $txt$Upacara peringatan setiap tanggal 24 Maret$txt$, $txt$Lagu Halo-Halo Bandung sebagai warisan budaya perjuangan$txt$, $txt$Museum-museum sejarah di Bandung yang menyimpan dokumentasi peristiwa$txt$])));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, created_by, updated_by, attribution_type, status)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari bab ini, siswa diharapkan mampu: (1) menjelaskan pengertian laju reaksi, (2) menjelaskan teori tumbukan sebagai dasar terjadinya reaksi, (3) mengidentifikasi faktor-faktor yang mempengaruhi laju reaksi, (4) menentukan persamaan laju reaksi dari data percobaan, dan (5) menghitung laju reaksi sederhana.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian Laju Reaksi dan Teori Tumbukan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Laju reaksi adalah ukuran seberapa cepat suatu reaksi kimia berlangsung, dinyatakan sebagai perubahan konsentrasi pereaksi atau hasil reaksi per satuan waktu, dengan satuan mol per liter per detik (M/s). Menurut teori tumbukan, reaksi terjadi ketika partikel-partikel pereaksi bertumbukan, tetapi tidak semua tumbukan menghasilkan reaksi: tumbukan harus memiliki energi yang cukup (melebihi energi aktivasi) dan orientasi yang tepat. Semakin banyak tumbukan efektif per detik, semakin cepat reaksi berlangsung.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'HEADING', 4, jsonb_build_object('text', $txt$Faktor yang Mempengaruhi Laju Reaksi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Konsentrasi: semakin besar konsentrasi, semakin banyak partikel per satuan volume, tumbukan meningkat, laju bertambah.$txt$, $txt$Suhu: kenaikan suhu membuat partikel bergerak lebih cepat; aturan praktisnya setiap kenaikan 10 derajat Celsius laju menjadi sekitar dua kali lipat. Inilah alasan makanan lebih awet di kulkas.$txt$, $txt$Luas permukaan: zat padat bereaksi lebih cepat jika luas permukaannya lebih besar, misalnya serbuk kayu terbakar lebih cepat daripada balok kayu.$txt$, $txt$Katalis: zat yang mempercepat reaksi dengan menurunkan energi aktivasi tanpa ikut habis bereaksi, misalnya enzim katalase dalam tubuh.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'HEADING', 6, jsonb_build_object('text', $txt$Persamaan Laju Reaksi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Untuk reaksi aA + bB menjadi hasil, persamaan lajunya adalah v = k [A]^m [B]^n, dengan k tetapan laju reaksi, dan m serta n adalah orde reaksi terhadap A dan B yang ditentukan dari percobaan, bukan dari koefisien reaksi. Contoh: data percobaan menunjukkan saat [A] dinaikkan dua kali lipat laju naik 4 kali (orde A = 2) dan saat [B] dinaikkan dua kali lipat laju naik 2 kali (orde B = 1), maka persamaan lajunya v = k [A]^2 [B].$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Jelaskan perbedaan tumbukan biasa dan tumbukan efektif menurut teori tumbukan.$txt$, $txt$Mengapa makanan lebih cepat basi di suhu ruang daripada di dalam kulkas? Jelaskan dengan konsep laju reaksi.$txt$, $txt$Sebutkan empat faktor yang mempengaruhi laju reaksi beserta penjelasan singkatnya.$txt$, $txt$Diketahui reaksi X + Y menjadi hasil. Data: [X]=0,2 M, [Y]=0,1 M, v=4 x 10^-4 M/s; [X]=0,4 M, [Y]=0,1 M, v=8 x 10^-4 M/s; [X]=0,2 M, [Y]=0,2 M, v=16 x 10^-4 M/s. Tentukan persamaan laju reaksinya.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'HEADING', 10, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a5, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Tumbukan efektif adalah tumbukan yang menghasilkan reaksi karena memiliki energi cukup (melebihi energi aktivasi) dan orientasi tepat; tumbukan biasa tidak memenuhi syarat tersebut.$txt$, $txt$Suhu ruang lebih tinggi sehingga partikel bergerak lebih cepat, tumbukan efektif lebih banyak, laju reaksi pembusukan meningkat.$txt$, $txt$Konsentrasi, suhu, luas permukaan, dan katalis.$txt$, $txt$Orde terhadap X = 1 (laju naik 2x saat [X] naik 2x), orde terhadap Y = 2 (laju naik 4x saat [Y] naik 2x). Persamaan: v = k [X] [Y]^2.$txt$])));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, created_by, updated_by, attribution_type, status)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari bab ini, siswa diharapkan mampu: (1) menjelaskan pengertian peta, (2) menyebutkan jenis-jenis peta, (3) mengidentifikasi unsur-unsur peta seperti judul, skala, legenda, dan mata angin, serta (4) membaca informasi sederhana dari sebuah peta.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Peta dan Jenis-jenisnya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Peta adalah gambaran permukaan bumi pada bidang datar dengan skala tertentu. Dengan peta, kita bisa mengetahui letak suatu tempat, jarak antar tempat, dan kondisi wilayah tanpa harus datang langsung ke sana. Orang yang ahli membuat peta disebut kartografer. Berdasarkan isinya, peta dibedakan menjadi peta umum yang menggambarkan kenampakan bumi secara umum (misalnya peta Indonesia) dan peta khusus/tematik yang menggambarkan hal tertentu (misalnya peta curah hujan). Berdasarkan bentuknya ada peta datar, peta timbul, dan globe yang berbentuk bola.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'HEADING', 4, jsonb_build_object('text', $txt$Unsur-Unsur Peta$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Judul peta: menunjukkan isi atau wilayah yang digambarkan$txt$, $txt$Skala: perbandingan jarak pada peta dengan jarak sebenarnya$txt$, $txt$Legenda: keterangan simbol-simbol yang dipakai pada peta$txt$, $txt$Mata angin: menunjukkan arah utara, selatan, timur, dan barat$txt$, $txt$Simbol: gambar sederhana untuk gunung, sungai, kota, jalan, dan lainnya$txt$, $txt$Warna: biru untuk perairan, hijau untuk dataran rendah, cokelat untuk pegunungan$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'HEADING', 6, jsonb_build_object('text', $txt$Membaca Skala, Simbol, dan Mata Angin$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Skala 1:100.000 artinya 1 cm pada peta sama dengan 100.000 cm (1 km) pada jarak sebenarnya. Sebelum membaca peta, lihat dulu legendanya agar tahu arti setiap simbol: garis biru berlekuk biasanya sungai, segitiga cokelat berarti gunung, titik hitam bisa berarti kota. Mata angin pada peta biasanya menunjuk ke arah utara; jika tahu utara, kita bisa menentukan arah lainnya. Contoh latihan: perhatikan peta provinsimu, temukan ibu kota provinsi, temukan sungai terpanjang, dan perkirakan jarak dari kotamu ke ibu kota provinsi menggunakan skala — membaca peta jadi terasa seperti berpetualang.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Apa yang dimaksud dengan peta?$txt$, $txt$Sebutkan empat unsur peta beserta fungsinya masing-masing!$txt$, $txt$Pada peta berskala 1:50.000, jarak dua desa adalah 4 cm. Berapa jarak sebenarnya kedua desa tersebut?$txt$, $txt$Warna apa yang biasanya dipakai untuk menunjukkan laut dan pegunungan pada peta?$txt$, $txt$Jika kamu menghadap utara, di arah manakah timur berada?$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'HEADING', 10, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_a6, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Peta adalah gambaran permukaan bumi pada bidang datar dengan skala tertentu.$txt$, $txt$Judul (menunjukkan isi peta), skala (perbandingan jarak), legenda (keterangan simbol), mata angin (penunjuk arah).$txt$, $txt$4 cm x 50.000 = 200.000 cm = 2 km.$txt$, $txt$Laut berwarna biru, pegunungan berwarna cokelat.$txt$, $txt$Timur berada di sebelah kanan saat menghadap utara.$txt$])));
